CREATE TABLE IF NOT EXISTS subjects (
  id TEXT PRIMARY KEY,
  position INTEGER NOT NULL,
  name_en TEXT NOT NULL,
  name_bn TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS subject_offerings (
  grade INTEGER NOT NULL,
  medium TEXT NOT NULL CHECK (medium IN ('bangla', 'english')),
  subject_id TEXT NOT NULL REFERENCES subjects(id),
  status TEXT NOT NULL CHECK (status IN ('books_supplied', 'books_not_supplied')),
  PRIMARY KEY (grade, medium, subject_id)
);

ALTER TABLE textbooks ADD COLUMN book_key TEXT;
ALTER TABLE textbooks ADD COLUMN extraction_method TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS textbooks_book_key ON textbooks (version_id, grade, medium, book_key) WHERE book_key IS NOT NULL;
ALTER TABLE source_pages ADD COLUMN confidence REAL;
