ALTER TABLE tutor_threads ADD COLUMN subject_key TEXT;
ALTER TABLE saved_items ADD COLUMN subject_key TEXT;
ALTER TABLE saved_items ADD COLUMN textbook_id TEXT;
CREATE INDEX IF NOT EXISTS saved_items_subject ON saved_items (user_id, subject_key);
