-- Database-level guard: a textbook can only be filed under a registered subject for an offered class and version.
CREATE TRIGGER IF NOT EXISTS textbooks_subject_guard_ins BEFORE INSERT ON textbooks
WHEN NOT EXISTS (SELECT 1 FROM subject_offerings o WHERE o.grade = NEW.grade AND o.medium = NEW.medium AND o.subject_id = NEW.subject_key)
BEGIN SELECT RAISE(ABORT, 'subject_not_in_registry'); END;
CREATE TRIGGER IF NOT EXISTS textbooks_subject_guard_upd BEFORE UPDATE OF grade, medium, subject_key ON textbooks
WHEN NOT EXISTS (SELECT 1 FROM subject_offerings o WHERE o.grade = NEW.grade AND o.medium = NEW.medium AND o.subject_id = NEW.subject_key)
BEGIN SELECT RAISE(ABORT, 'subject_not_in_registry'); END;

